import{_ as i,o,c as a,a3 as t,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/import-export-statistik/verwaltung-export-logineo-xml-01.png",l="/bilder/import-export-statistik/verwaltung-export-logineo-xml-02.png",p="/bilder/import-export-statistik/verwaltung-export-logineo-xml-03.png",d="/bilder/import-export-statistik/verwaltung-export-logineo-xml-04.png",u="/bilder/import-export-statistik/verwaltung-export-logineo-xml-05.png",k=JSON.parse('{"title":"Daten für LOGINEO NRW als XML exportieren","description":"","frontmatter":{"title":"Daten für LOGINEO NRW als XML exportieren","source_pageid":1173,"source_revision":4026},"headers":[],"relativePath":"schild3/import-export-statistik/export-fuer-logineo-nrw-xml-verwaltung-export.md","filePath":"schild3/import-export-statistik/export-fuer-logineo-nrw-xml-verwaltung-export.md"}'),g={name:"schild3/import-export-statistik/export-fuer-logineo-nrw-xml-verwaltung-export.md"};function h(c,r,m,x,w,f){return o(),a("div",null,[...r[0]||(r[0]=[t('<h1 id="daten-fur-logineo-nrw-als-xml-exportieren" tabindex="-1">Daten für LOGINEO NRW als XML exportieren <a class="header-anchor" href="#daten-fur-logineo-nrw-als-xml-exportieren" aria-label="Permalink to &quot;Daten für LOGINEO NRW als XML exportieren&quot;">​</a></h1><p>Wählen Sie die zu exportierenden Personen und Datenarten für LOGINEO NRW. Prüfen Sie insbesondere die Optionen für externe Schülerinnen und Schüler sowie Personengruppen.</p><p>Über diese Auswahl lassen sich Daten der Personen der Schule und Unterrichtsdaten so exportieren, dass sie anschließend in Logineo NRW importiert werden können.</p><h2 id="export-aus-schild" tabindex="-1">Export aus SchILD <a class="header-anchor" href="#export-aus-schild" aria-label="Permalink to &quot;Export aus SchILD&quot;">​</a></h2><p><a href="/bilder/import-export-statistik/verwaltung-export-logineo-xml-01.png"><img src="'+s+'" alt="Exportfenster unter Verwaltung ➜ Export ➜ Logineo NRW (XML)." loading="lazy"></a></p><p><em>Exportfenster unter Verwaltung ➜ Export ➜ Logineo NRW (XML).</em></p><p>Bei Aufruf des Exportfensters können einige Auswahlen vorgenommen werden:</p><ul><li><strong>Aktuelle Auswahl für Export verwenden</strong>: Hier werden nur Daten der Schülerinnen und Schüler im Container, d. h. der aktuellen Auswahl, exportiert. Ansonsten werden alle Schülerinnen und Schüler exportiert.</li><li><strong>Schüler mit Status &quot;Extern&quot; in Export einbeziehen</strong>: Hier werden auch Schülerinnen und Schüler anderer Schulen, die an der eigenen Schule unterrichtet werden (sog. Externe), exportiert.</li><li><strong>Nur Daten für Schüler und Lehrer ausgeben</strong>: Hier werden nur Daten der Schülerinnen und Schüler und Lehrerinnen und Lehrer ausgegeben. Ist dieser Haken nicht gesetzt, werden z. B. auch Ausbilderinnen und Ausbilder an Berufsschulen exportiert.</li><li><strong>Nur Personengruppen mit E-Mail-Verteiler exportieren</strong>: Logineo kann auch Personengruppen verwalten, ähnlich wie SchILD. Hier kann gesteuert werden, ob Personengruppen mit oder ohne eingerichteten E-Mail-Verteilern ebenfalls exportiert werden sollen.</li><li><strong>Schüler mit Status &quot;Beurlaubt&quot; in Export einbeziehen</strong>: Hier wird gesteuert, ob auch Schülerinnen und Schüler mit Status &quot;Beurlaubt&quot; in den Export einbezogen werden.</li></ul><p>Zusätzlich kann das Schuljahr und der Abschnitt für den Export festgelegt werden.</p><p>Die Daten der Exportdatei sind verschlüsselt. In diesem Exportfenster muss daher das Kennwort eingegeben und wiederholt werden.</p><p>Verwenden Sie beim Import in LOGINEO NRW dasselbe Kennwort, um die Exportdatei zu entschlüsseln.</p><p><a href="/bilder/import-export-statistik/verwaltung-export-logineo-xml-02.png"><img src="'+l+'" alt="Umgang mit Fehlern während des Exports." loading="lazy"></a></p><p><em>Umgang mit Fehlern während des Exports.</em></p><p>Während des Exports kann es unter Umständen zu Fehlern kommen, beispielsweise auf Grund von nicht oder falsch angelegter E-Mail-Adressen der Personen der Schule</p><p>Das dann erscheinende Fenster kann durch einen Klick auf <code>Schließen</code> geschlossen werden, worauf ausgewählt werden kann, ob der Export fortgesetzt werden kann. Prüfen Sie zuerst die gemeldeten Datensätze. Setzen Sie den Export nur fort, wenn die ausgelassenen oder fehlerhaften Angaben für den geplanten Import geklärt sind; korrigieren Sie die Ausgangsdaten andernfalls in SchILD und exportieren Sie erneut.</p><p>Nach dem Export findet sich im angegebenen Exportverzeichnis eine Zip-Datei. Deren Inhalt, eine XML-Datei, kann nicht geöffnet oder entpackt werden. Logineo NRW verwendet die Zip-Datei direkt, ohne dass diese entpackt werden muss.</p>',16),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Beachten Sie den Unterschied von "),e("em",null,"Logineo NRW LMS"),n(" und "),e("em",null,"Logineo NRW"),n(". Diese Angebote lesen jeweils unterschiedliche Exportdaten von SchILD-NRW ein.")])],-1),t('<h2 id="import-in-logineo-nrw" tabindex="-1">Import in Logineo NRW <a class="header-anchor" href="#import-in-logineo-nrw" aria-label="Permalink to &quot;Import in Logineo NRW&quot;">​</a></h2><p><a href="/bilder/import-export-statistik/verwaltung-export-logineo-xml-03.png"><img src="'+p+'" alt="Import in Logineo NRW (Schritt 1)." loading="lazy"></a></p><p><em>Import in Logineo NRW (Schritt 1).</em></p><p>Nach dem Login muss in der Sidebar die Schaltfläche <strong>Administration</strong> ausgewählt werden.</p><p><a href="/bilder/import-export-statistik/verwaltung-export-logineo-xml-04.png"><img src="'+d+'" alt="Import in Logineo NRW (Schritt 2)." loading="lazy"></a></p><p><em>Import in Logineo NRW (Schritt 2).</em></p><p>Im folgenden Fenster kann durch Klick auf den Werkzeugkoffer der <strong>Import</strong> ausgewählt werden.</p><p><a href="/bilder/import-export-statistik/verwaltung-export-logineo-xml-05.png"><img src="'+u+'" alt="Import in Logineo NRW (Schritt 3)." loading="lazy"></a></p><p><em>Import in Logineo NRW (Schritt 3).</em></p><p>Für den Import in Logineo NRW ist ein Administratorzugang erforderlich.</p><p>Klicken Sie auf <strong>Datei auswählen</strong>, wählen Sie die zuvor exportierte ZIP-Datei und geben Sie das beim Export festgelegte <strong>Kennwort</strong> ein. Es folgt der Importprozess, bei dem durch Logineo NRW auch Lösungen für auftretende Importkonflikte vorgeschlagen werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Export_f%C3%BCr_Logineo_NRW_(XML)_(Verwaltung_Export)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4026.</p>',13)])])}const _=i(g,[["render",h]]);export{k as __pageData,_ as default};
